package io.xeros.content.questing;
import io.xeros.model.entity.player.Player;import io.xeros.model.entity.npc.NPC;import java.util.*;
import io.xeros.content.achievement_diary.impl.*;
public final class RuneMysteries extends ClassicQuest {
 public RuneMysteries(Player p){super(p);}public String getName(){return "Rune Mysteries";}public String getDisplayName(){return "Misterios das runas";}public int getCompletionStage(){return 5;}
 public List<String> getCompletedRewardsList(){return Arrays.asList("1 ponto de missao","Air talisman devolvido","Transporte para a Rune essence mine");}
 public List<String> getJournalText(int s){switch(s){case 0:return Arrays.asList("Fale com Duke Horacio no primeiro andar do castelo de Lumbridge.");case 1:return Arrays.asList("Leve o Air talisman do Duke a Archmage Sedridor.","Ele esta no subsolo da Wizards' Tower, ao sul de Draynor.");case 2:return Arrays.asList("Sedridor descobriu que o talisma se conecta a antigos altares.","Leve o Research package a Aubury, na loja de runas de Varrock.");case 3:return Arrays.asList("Aubury esta examinando as pesquisas.","Fale com ele novamente para recolher suas notas.");case 4:return Arrays.asList("Leve as Notes de Aubury a Sedridor no subsolo da torre.");default:return Arrays.asList("Os magos redescobriram a mina de essencia e os talismas.","Sedridor e Aubury podem me transportar para a mina.");}}
 public void giveQuestCompletionRewards(){exactReward(20,0);}
 private void mine(boolean sedridor){player.getPA().startTeleport(2929,4813,0,"modern",false);if(sedridor)player.getDiaryManager().getLumbridgeDraynorDiary().progress(LumbridgeDraynorDiaryEntry.TELEPORT_ESSENCE_LUM);else player.getDiaryManager().getVarrockDiary().progress(VarrockDiaryEntry.TELEPORT_ESSENCE_VAR);}
 public boolean handleNpcClick(NPC n,int option){int id=n.getNpcId();boolean duke=id==815&&local(n,3210,3221,1),sed=id==5034&&local(n,3101,9570,0),aub=id==2886&&local(n,3253,3401,0);if(!duke&&!sed&&!aub)return false;if(!ready()||!nearbyNpc(n))return true;int s=getStage();
 if((sed&&option==2||aub&&option==3)){if(isQuestCompleted())mine(sed);else say(id,"Primeiro precisamos concluir a pesquisa sobre o talisma.");return true;}
 if(option!=1)return false;
 if(duke){if(s==0)offer(n,0,"Encontrei um talisma misterioso. Os magos da Wizards' Tower talvez reconhecam seu poder.","Vou levar o talisma aos magos.",()->{if(exchange(new int[0][],new int[][]{{1438,1}})){step(0,1);say(id,"Procure Archmage Sedridor no subsolo da torre ao sul de Draynor.");}});else if(s==1&&!owns(1438))offer(n,s,"Os magos ainda precisam ver o talisma.","Pedir outro talisma.",()->replace(1438));else say(id,"Os magos na Wizards' Tower podem esclarecer o misterio.");}
 else if(sed){if(s==0)say(id,"O Duke Horacio pode ter algo interessante para nossa pesquisa.");
 else if(s==1)offer(n,s,"Esse e um Air talisman! Pode ser a chave para recuperar a arte de criar runas.","Entregar o Air talisman.",()->{if(exchange(new int[][]{{1438,1}},new int[][]{{290,1}})){step(1,2);say(id,"Leve este Research package a Aubury, na loja de runas de Varrock.","Precisamos comparar minhas descobertas com as pesquisas dele.");}});
 else if(s==2&&!owns(290))offer(n,s,"Aubury precisa das minhas pesquisas.","Pedir outro Research package.",()->replace(290));
 else if(s==4)offer(n,s,"As observacoes de Aubury confirmam minha teoria. Podemos voltar a extrair essencia e usar os altares antigos!","Entregar Notes e concluir a pesquisa.",()->{if(exchange(new int[][]{{291,1}},new int[][]{{1438,1}})){finish(4,20,0);player.sendMessage("Sedridor devolve o Air talisman. Use Teleport para visitar a mina.");}});
 else if(isQuestCompleted())offer(n,s,"A essencia da mina permite criar runas nos altares. Leve o talisma correspondente.","Viajar para a Rune essence mine.",()->mine(true));else say(id,"Aubury, na loja de runas de Varrock, precisa examinar as pesquisas.");}
 else{if(s==2)offer(n,s,"Sedridor enviou novas pesquisas? Vou compara-las com minhas anotacoes.","Entregar Research package.",()->{if(exchange(new int[][]{{290,1}},new int[0][])){step(2,3);say(id,"Muito interessante! Fale comigo novamente para levar minha resposta.");}});
 else if(s==3)offer(n,s,"Sedridor estava certo! Estas notas devem ajuda-lo a concluir a pesquisa.","Receber as Notes de Aubury.",()->{if(exchange(new int[0][],new int[][]{{291,1}})){step(3,4);say(id,"Volte a Sedridor no subsolo da Wizards' Tower.");}});
 else if(s==4&&!owns(291))offer(n,s,"Sedridor precisa das minhas observacoes.","Pedir outra copia das Notes.",()->replace(291));
 else if(isQuestCompleted())offer(n,s,"Podemos viajar novamente para a fonte de essencia.","Viajar para a Rune essence mine.",()->mine(false));else say(id,"Estou pesquisando a origem das runas com Sedridor.");}return true;}
}
